import json, os, sys
from playwright.sync_api import sync_playwright

BASE = "http://127.0.0.1:5002"
TEMP = os.environ["TEMP"]
out = {}

def page_checks(page, path, shot_name, log):
    resp_log = []
    page.on("response", lambda r: resp_log.append((r.url, r.status)))
    page.on("requestfailed", lambda r: log["failed"].append(f"{r.url} {r.failure}"))
    resp = page.goto(BASE + path, wait_until="networkidle")
    res = {"status": resp.status if resp else None, "url": page.url}
    res["stylesheets"] = page.evaluate("""() => Array.from(document.querySelectorAll('link[rel=stylesheet]')).map(l => l.getAttribute('href'))""")
    css = [x for x in resp_log if "style.css" in x[0]]
    res["style_css_requests"] = css
    res["scrollWidth"] = page.evaluate("document.documentElement.scrollWidth")
    res["innerWidth"] = page.evaluate("window.innerWidth")
    res["btn_nav_small"] = page.evaluate("""() => {
        const els = Array.from(document.querySelectorAll('a.btn, nav a'));
        return els.map(e => ({text: e.textContent.trim().slice(0,40), minHeight: getComputedStyle(e).minHeight, boxH: Math.round(e.getBoundingClientRect().height*10)/10, display: getComputedStyle(e).display}));
    }""")
    res["min_font"] = page.evaluate("""() => {
        let min = null, who = null;
        const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
        while (walker.nextNode()) {
            const t = walker.currentNode;
            if (!t.textContent.trim()) continue;
            const el = t.parentElement;
            const fs = parseFloat(getComputedStyle(el).fontSize);
            if (min === null || fs < min) { min = fs; who = el.tagName + ' "' + t.textContent.trim().slice(0,30) + '"'; }
        }
        return {min, who};
    }""")
    page.screenshot(path=os.path.join(TEMP, shot_name), full_page=True)
    res["screenshot"] = os.path.join(TEMP, shot_name)
    return res

with sync_playwright() as p:
    browser = p.chromium.launch(headless=True)
    log = {"console": [], "failed": []}
    ctx = browser.new_context(viewport={"width": 375, "height": 812}, device_scale_factor=2)
    page = ctx.new_page()
    page.on("console", lambda m: log["console"].append(f"{m.type}: {m.text}") if m.type in ("error", "warning") else None)
    page.on("pageerror", lambda e: log["console"].append(f"pageerror: {e}"))
    out["home_375"] = page_checks(page, "/", "surplus_home_375.png", log)
    out["about_375"] = page_checks(page, "/about", "surplus_about_375.png", log)
    # navigate back home and click persona link
    page.goto(BASE + "/", wait_until="networkidle")
    try:
        link = page.get_by_role("link", name="Mess Donor 1 (Synthetic)")
        count = link.count()
        link.first.click()
        page.wait_for_load_state("networkidle")
        header = page.evaluate("document.querySelector('header') ? document.querySelector('header').innerText : document.body.innerText.slice(0,300)")
        out["persona_click"] = {"link_count": count, "url": page.url, "header_has_acting_as": "Acting as Mess Donor 1 (Synthetic)" in header, "header_text": header[:200]}
    except Exception as e:
        out["persona_click"] = {"error": str(e)[:300]}
    ctx.close()
    ctx2 = browser.new_context(viewport={"width": 1280, "height": 800}, device_scale_factor=1)
    page2 = ctx2.new_page()
    page2.goto(BASE + "/", wait_until="networkidle")
    out["home_1280"] = {"scrollWidth": page2.evaluate("document.documentElement.scrollWidth"), "innerWidth": page2.evaluate("window.innerWidth")}
    ctx2.close()
    browser.close()
out["console_errors"] = log["console"]
out["failed_requests"] = log["failed"]
print(json.dumps(out, indent=1))
'@; Set-Content -Path (Join-Path $dir 'check.py') -Value $code -Encoding UTF8; & (Join-Path $dir 'Scripts\python.exe') (Join-Path $dir 'check.py')

