BASE = "http://127.0.0.1:5002"
out = {}

with sync_playwright() as p:
    b = p.chromium.launch(headless=True)

    def audit(path, label, shot=None, vw=375, vh=812, scale=2):
        ctx = b.new_context(viewport={"width": vw, "height": vh}, device_scale_factor=scale)
        pg = ctx.new_page()
        console_errs, failed = [], []
        pg.on("console", lambda m: console_errs.append(f"{m.type}: {m.text}") if m.type in ("error", "warning") else None)
        pg.on("pageerror", lambda e: console_errs.append(f"pageerror: {e}"))
        pg.on("requestfailed", lambda r: failed.append(f"{r.url} {r.failure}"))
        css = {}
        def on_resp(r):
            if "style.css" in r.url:
                css["status"] = r.status
        pg.on("response", on_resp)
        resp = pg.goto(BASE + path, wait_until="load")
        info = {"http_status": resp.status if resp else None}
        info["scrollWidth"] = pg.evaluate("() => document.documentElement.scrollWidth")
        info["innerWidth"] = pg.evaluate("() => window.innerWidth")
        info["hscroll"] = info["scrollWidth"] > info["innerWidth"]
        info["style_css_status"] = css.get("status", "NOT REQUESTED")
        info["body_font_size"] = pg.evaluate("() => getComputedStyle(document.body).fontSize")
        info["min_font_size_text_elems"] = pg.evaluate("""() => {
            let m = null, who = null;
            for (const el of document.querySelectorAll('body *')) {
                const t = Array.from(el.childNodes).filter(n => n.nodeType === 3 && n.textContent.trim()).length;
                if (!t) continue;
                const fs = parseFloat(getComputedStyle(el).fontSize);
                if (m === null || fs < m) { m = fs; who = el.tagName + '.' + el.className; }
            }
            return [m, who];
        }""")
        info["touch_targets"] = pg.evaluate("""() => Array.from(document.querySelectorAll('a.btn, nav a')).map(el => {
            const cs = getComputedStyle(el), r = el.getBoundingClientRect();
            return {text: el.textContent.trim().slice(0,40), minHeight: cs.minHeight, rectH: Math.round(r.height*10)/10, display: cs.display};
        })""")
        if shot:
            pg.screenshot(path=shot, full_page=True)
            info["screenshot"] = shot
        info["console_errors_warnings"] = console_errs
        info["failed_requests"] = failed
        out[label] = info
        return pg, ctx

    pg, ctx = audit("/", "home_375", shot=os.path.join(TMP, "surplus_home_375.png"))
    audit("/about", "about_375", shot=os.path.join(TMP, "surplus_about_375.png"))
    ctx.close()
    _, ctx2 = audit("/", "home_1280", vw=1280, vh=800, scale=1)
    ctx2.close()

    # Click the demo persona on home at 375
    ctx3 = b.new_context(viewport={"width": 375, "height": 812}, device_scale_factor=2)
    pg3 = ctx3.new_page()
    pg3.goto(BASE + "/", wait_until="load")
    click = {}
    try:
        loc = pg3.get_by_text("Mess Donor 1 (Synthetic)", exact=False)
        click["matches"] = loc.count()
        loc.first.click(timeout=5000)
        pg3.wait_for_load_state("load")
        click["url_after"] = pg3.url
        click["header_has_acting_as"] = pg3.evaluate("() => document.body.innerText.includes('Acting as Mess Donor 1 (Synthetic)')")
        click["hscroll_after"] = pg3.evaluate("() => document.documentElement.scrollWidth > window.innerWidth")
    except Exception as e:
        click["error"] = str(e)[:500]
    out["click_mess_donor_1"] = click
    ctx3.close()
    b.close()

print(json.dumps(out, indent=1, default=str))
