/* SurplusLink base styles: mobile-first, single column by default. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  margin: 0;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

img,
pre,
table {
  max-width: 100%;
}

pre {
  overflow-x: auto;
}

.container {
  max-width: 960px;
  margin: 0 auto;
  padding: 12px;
}

/* Banner shown on every page */
.demo-banner {
  background: #fff3cd;
