{% extends "base.html" %}
{% block title %}Post surplus food{% endblock %}
{% block content %}
<h1>Post surplus food</h1>
<p>Takes about a minute. Pickup-by is the collection deadline you set, in IST.</p>

{% if errors %}
<div class="error-summary" role="alert">
  <p>Please fix the highlighted fields.</p>
</div>
{% endif %}

<form method="post" action="{{ url_for('donations.new_listing') }}" novalidate>
  <div class="field">
    <label for="description">Food description</label>
    <input type="text" id="description" name="description" maxlength="200" value="{{ values.get('description', '') }}" required
      {% if errors.get('description') %}aria-invalid="true" aria-describedby="description-error"{% endif %}>
    {% if errors.get('description') %}<p class="field-error" id="description-error">{{ errors.get('description') }}</p>{% endif %}
  </div>

  <div class="field">
    <label for="quantity_kg">Quantity (kg)</label>
    <input type="number" id="quantity_kg" name="quantity_kg" step="0.1" min="0.1" max="1000" inputmode="decimal" value="{{ values.get('quantity_kg', '') }}" required
      {% if errors.get('quantity_kg') %}aria-invalid="true" aria-describedby="quantity_kg-error"{% endif %}>
    {% if errors.get('quantity_kg') %}<p class="field-error" id="quantity_kg-error">{{ errors.get('quantity_kg') }}</p>{% endif %}
  </div>

  <div class="field">
    <label for="pickup_by">Pickup-by deadline (IST)</label>
    <input type="datetime-local" id="pickup_by" name="pickup_by" value="{{ values.get('pickup_by', '') }}" required
      {% if errors.get('pickup_by') %}aria-invalid="true" aria-describedby="pickup_by-error"{% endif %}>
    <p class="helper">The collection deadline you set, in IST. Donor-provided, not a food-safety guarantee.</p>
    {% if errors.get('pickup_by') %}<p class="field-error" id="pickup_by-error">{{ errors.get('pickup_by') }}</p>{% endif %}
  </div>

  <div class="field">
    <label for="storage_type">Storage type</label>
    <select id="storage_type" name="storage_type" required
      {% if errors.get('storage_type') %}aria-invalid="true" aria-describedby="storage_type-error"{% endif %}>
      <option value="" disabled {% if not values.get('storage_type') %}selected{% endif %}>Choose storage</option>
      {% for key, label in storage_options %}
      <option value="{{ key }}" {% if values.get('storage_type') == key %}selected{% endif %}>{{ label }}</option>
      {% endfor %}
    </select>
    {% if errors.get('storage_type') %}<p class="field-error" id="storage_type-error">{{ errors.get('storage_type') }}</p>{% endif %}
  </div>

  <div class="field">
    <label for="handling_notes">Handling information (optional)</label>
    <textarea id="handling_notes" name="handling_notes" maxlength="500" rows="3"
      {% if errors.get('handling_notes') %}aria-invalid="true" aria-describedby="handling_notes-error"{% endif %}>{{ values.get('handling_notes', '') }}</textarea>
    <p class="helper">e.g. keep covered, reheated before serving, contains cooked rice</p>
    {% if errors.get('handling_notes') %}<p class="field-error" id="handling_notes-error">{{ errors.get('handling_notes') }}</p>{% endif %}
  </div>

  <fieldset {% if errors.get('allergens') %}aria-invalid="true" aria-describedby="allergens-error"{% endif %}>
    <legend>Allergens present (tick all that apply)</legend>
    {% for a in allergen_options %}
    <label class="check"><input type="checkbox" name="allergens" value="{{ a }}" {% if a in values.getlist('allergens') %}checked{% endif %}> {{ a|capitalize }}</label>
    {% endfor %}
    <p class="helper">As declared by the donor. SurplusLink does not verify allergen information.</p>
    {% if errors.get('allergens') %}<p class="field-error" id="allergens-error">{{ errors.get('allergens') }}</p>{% endif %}
  </fieldset>

  <button type="submit" class="btn">Post surplus</button>
</form>

<p class="notice">SurplusLink coordinates donations and does not certify food safety.</p>
{% endblock %}

