﻿import os, re, sqlite3, traceback
from datetime import datetime
from playwright.sync_api import sync_playwright

BASE = "http://127.0.0.1:5006"
TEMP = os.environ["TEMP"]
DB = os.path.join(TEMP, "surplus_m2_check.db")
SHOT = os.path.join(TEMP, "surplus_matches_375.png")

con = sqlite3.connect(DB)
donor_pid, donor_org = con.execute(
    "SELECT id, organisation_id FROM persona WHERE role='donor' ORDER BY id LIMIT 1").fetchone()
print("donor persona id", donor_pid, "org id", donor_org)

console_log = []
net_log = []

def step(name, fn):
    try:
        fn()
    except Exception:
        print("STEP", name, "ERROR")
        traceback.print_exc()

with sync_playwright() as p:
    b = p.chromium.launch(headless=True)
    ctx = b.new_context(viewport={"width": 375, "height": 812}, device_scale_factor=2)
    page = ctx.new_page()
    page.set_default_timeout(10000)
    page.on("console", lambda m: console_log.append(f"console.{m.type}: {m.text}") if m.type in ("error", "warning") else None)
    page.on("pageerror", lambda e: console_log.append(f"pageerror: {e}"))
    page.on("requestfailed", lambda r: net_log.append(f"requestfailed {r.method} {r.url} {r.failure}"))
    page.on("response", lambda r: net_log.append(f"HTTP {r.status} {r.request.method} {r.url}") if r.status >= 400 else None)

    r = page.goto(f"{BASE}/role/{donor_pid}", wait_until="domcontentloaded")
    print("role select: status", r.status, "url", page.url)

    state = {}

    def step_a():
        page.goto(f"{BASE}/donate", wait_until="domcontentloaded")
        page.fill("#description", "Test dal rice")
        page.fill("#quantity_kg", "12.5")
        page.fill("#pickup_by", "2030-01-01T15:00")
        page.select_option("#storage_type", "chilled")
        page.fill("#handling_notes", "Keep covered")
        page.check("input[name=allergens][value=dairy]")
        page.click("button[type=submit]")
        page.wait_for_url(re.compile(r".*/listings/\d+.*"), wait_until="domcontentloaded")
        state["listing_id"] = int(re.search(r"/listings/(\d+)", page.url).group(1))
        print("a: resulting URL", page.url, "listing_id", state["listing_id"])
    step("a", step_a)

    def step_b():
        link = page.locator("a:has-text('See ranked matches')")
        n = link.count()
        print("b: 'See ranked matches' count", n, "href", link.first.get_attribute("href") if n else None)
    step("b", step_b)

    def step_c():
        resp = page.goto(f"{BASE}/listings/{state['listing_id']}/matches", wait_until="domcontentloaded")
        body = page.content()
        print("c: status", resp.status, "url", page.url)
        print("c: has 'Ranked matches'", "Ranked matches" in body, "| has 'Assumptions'", "Assumptions" in body)
        print("c: li.match total", page.locator("li.match").count(),
              "| receivers ol", page.locator("ol.matches").nth(0).locator(":scope > li.match").count(),
              "| volunteers ol", page.locator("ol.matches").nth(1).locator(":scope > li.match").count())
    step("c", step_c)

    def step_d():
        d = page.evaluate("""() => {
            const iw = window.innerWidth, sw = document.documentElement.scrollWidth;
            const wide = [];
            document.querySelectorAll('body *').forEach(el => {
                const r = el.getBoundingClientRect();
                if (r.right > iw + 0.5) {
                    const cls = (typeof el.className === 'string' && el.className) ? '.' + el.className.trim().split(/\\s+/).join('.') : '';
                    const inTableWrap = !!el.closest('.table-wrap');
                    wide.push(el.tagName.toLowerCase() + cls + ' right=' + Math.round(r.right) + (inTableWrap ? ' [inside .table-wrap]' : ''));
                }
            });
            return {iw, sw, wide};
        }""")
        print("d: innerWidth", d["iw"], "scrollWidth", d["sw"], "elements wider than innerWidth:", len(d["wide"]))
        for w in d["wide"][:25]:
            print("   ", w)
    step("d", step_d)

    def step_e():
        cards = page.evaluate("""() => {
            const out = [];
            document.querySelectorAll('ol.matches').forEach((ol, idx) => {
                const kind = idx === 0 ? 'receiver' : 'volunteer';
                ol.querySelectorAll(':scope > li.match').forEach(li => {
                    const ps = Array.from(li.querySelectorAll('p'));
                    const sc = ps.find(p => p.textContent.trim().startsWith('Score'));
                    out.push({kind,
                        name: li.querySelector('h3').textContent.trim(),
                        eligible: !!li.querySelector('.tag-eligible'),
                        score: sc ? sc.textContent.trim() : null,
                        reasons: Array.from(li.querySelectorAll('ul.reasons li')).map(x => x.textContent.trim())});
                });
            });
            return out;
        }""")
        recv = [c for c in cards if c["kind"] == "receiver"]
        el = [c for c in recv if c["eligible"]]
        inel = [c for c in recv if not c["eligible"]]
        print("e: receivers total", len(recv), "eligible", len(el), "ineligible", len(inel))
        if el:
            print("e: first eligible receiver:", el[0]["name"], "|", el[0]["score"])
        else:
            print("e: no eligible receiver")
        if inel:
            print("e: first ineligible receiver:", inel[0]["name"], "| reasons:", inel[0]["reasons"])
        else:
            print("e: no ineligible receiver")
        state["recv_eligible"] = len(el)
    step("e", step_e)

    def step_f():
        page.screenshot(path=SHOT, full_page=True)
        print("f: screenshot written to $env:TEMP\\surplus_matches_375.png, exists:", os.path.exists(SHOT))
    step("f", step_f)

    def step_g():
        print("g: console errors/warnings:", len(console_log))
        for c in console_log:
            print("   ", c)
        print("g: failed requests / HTTP>=400:", len(net_log))
        for n in net_log:
            print("   ", n)
    step("g", step_g)

    def step_h():
        con.execute(
            "INSERT INTO listing (donor_org_id, description, quantity_kg, pickup_by_utc, storage_type, "
            "handling_notes, allergens, status, created_at_utc, updated_at_utc) "
            "VALUES (?, 'Expired test listing', 5, '2020-01-01T00:00:00+00:00', 'chilled', '', '', 'posted', "
            "'2025-01-01T06:00:00+00:00', '2025-01-01T06:00:00+00:00')",
            (donor_org,))
        con.commit()
        eid = con.execute("SELECT max(id) FROM listing").fetchone()[0]
        state["expired_id"] = eid
        resp = page.goto(f"{BASE}/listings/{eid}/matches", wait_until="domcontentloaded")
        body = page.content()
        err = page.locator(".error-summary").all_inner_texts()
        print("h: expired listing id", eid, "status", resp.status)
        print("h: 'Pickup-by deadline has passed.' present:", "Pickup-by deadline has passed." in body)
        print("h: error-summary text:", err)
    step("h", step_h)

    def step_i():
        resp = page.goto(f"{BASE}/listings/{state['listing_id']}/matches", wait_until="domcontentloaded")
        body = page.content()
        print("i: test listing matches: 'No suitable receivers' present:", "No suitable receivers" in body,
              "| eligible receivers counted in step e:", state.get("recv_eligible"))
    step("i", step_i)

    b.close()
con.close()
print("DONE")

--- surpluslink\surplus_link\templates\board.html ---
{% extends "base.html" %}
{% block title %}Volunteer board{% endblock %}
{% block content %}
<h1>Volunteer pickup board</h1>
<p class="notice">Claimed listings waiting for a volunteer. Times are IST. Pickup-by is a donor-provided collection deadline, not a guarantee of food safety.</p>

<section class="board" data-refresh-seconds="12">
  <p class="helper">Last updated <span id="last-updated">{{ last_updated_utc | ist }}</span>. <a href="{{ request.path }}">Refresh now</a></p>

  <h2>Open pickups</h2>
  {% if board.open %}
  <ol class="matches">
    {% for item in board.open %}
    <li class="match">
      <h3>{{ item.description }}</h3>
      <p>{{ item.quantity_kg }} kg from {{ item.donor_name }} to {{ item.receiver_name }}</p>
      <p>Pickup-by {{ item.pickup_by_utc | ist }}</p>
      {% if item.eligible %}
      <p class="tag-eligible">Suitable for you</p>
      <form method="post" action="{{ url_for('volunteering.accept_pickup_view', listing_id=item.listing_id) }}"><button type="submit" class="btn">Accept pickup</button></form>
      {% else %}
      <p class="tag-ineligible">Not suitable</p>
      <ul class="reasons">
        {% for r in item.reasons %}<li>{{ r }}</li>{% endfor %}
      </ul>
      {% endif %}
    </li>
    {% endfor %}
  </ol>
  {% else %}
  <p class="notice">No open pickups right now.</p>
  {% endif %}

  <h2>My pickups</h2>
  {% if board.mine %}
  <ol class="matches">
    {% for item in board.mine %}
    <li class="match">
      <h3>{{ item.description }}</h3>
      <p>Status: {{ item.status|capitalize }}</p>
      <p>Pickup-by {{ item.pickup_by_utc | ist }}</p>
      <p><a href="{{ url_for('donations.listing_detail', listing_id=item.listing_id) }}">Open listing and timeline</a></p>
      {% if item.status == 'claimed' %}
      <form method="post" action="{{ url_for('volunteering.collect_view', listing_id=item.listing_id) }}"><button type="submit" class="btn">Mark collected</button></form>
      {% endif %}
      {% if item.status == 'collected' %}
      <form method="post" action="{{ url_for('volunteering.deliver_view', listing_id=item.listing_id) }}"><button type="submit" class="btn">Mark delivered</button></form>
      {% endif %}
    </li>
    {% endfor %}
  </ol>
  {% else %}
  <p class="notice">No pickups assigned to you yet.</p>
  {% endif %}
</section>

<script src="{{ url_for('static', filename='refresh.js') }}" defer></script>
{% endblock %}

