--- surpluslink\surplus_link\templates\base.html ---
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <link rel="stylesheet" href="{{ url_for('static', filename='style.css') }}">
  <title>{% block title %}{% endblock %} - SurplusLink</title>
  <style>
    body { font-family: system-ui, sans-serif; margin: 0; padding: 0 1rem 2rem; line-height: 1.4; color: #1d1d1d; }
    header, main, footer { max-width: 40rem; margin: 0 auto; }
    header { padding-top: 1rem; }
    nav a, ul.personas a { display: inline-flex; align-items: center; min-height: 44px; margin-right: 0.75rem; }
    .badge { background: #fff3c4; border: 1px solid #c9a400; padding: 0.1rem 0.4rem; border-radius: 4px; font-size: 0.85rem; }
    .acting { background: #e8f4ff; padding: 0.4rem 0.6rem; border-radius: 4px; }
    ul.personas { list-style: none; padding: 0; }
    ul.personas li { padding: 0.5rem 0; border-bottom: 1px solid #eee; }
    footer { margin-top: 2rem; font-size: 0.85rem; color: #555; }
  </style>
</head>
<body>
<header>
  <strong>SurplusLink</strong> <span class="badge">Synthetic-data demo</span>
  <nav>
    <a href="{{ url_for('main.home') }}">Home</a>
    <a href="{{ url_for('main.about') }}">About</a>
    <a href="{{ url_for('impact.dashboard') }}">Impact</a>
    {% if current_persona %}<a href="{{ url_for('main.switch') }}">Switch role</a>{% endif %}
{% if current_persona and current_persona.role == 'donor' %}<a href="{{ url_for('donations.new_listing') }}">Post surplus</a>{% endif %}
{% if current_persona and current_persona.role == 'volunteer' %}<a href="{{ url_for('volunteering.board') }}">Volunteer board</a>{% endif %}
  </nav>
  {% if current_persona %}
  <p class="acting">Acting as {{ current_persona.display_name }} ({{ current_persona.role }})</p>
  {% endif %}
</header>
<main>
  {% block content %}{% endblock %}
</main>
<footer>
  <p>Synthetic-data demo. SurplusLink coordinates donations and does not certify food safety. Pickup-by is a donor-provided collection deadline, not a guarantee of food safety. Nothing here is a tax or legal benefit claim.</p>
</footer>
</body>
</html>


--- surpluslink\surplus_link\templates\home.html ---
{% extends "base.html" %}
{% block title %}Choose a demo persona{% endblock %}
{% block content %}
<h1>Choose a demo persona</h1>
<p>Pick a synthetic persona to act as. No real accounts or personal details are used.</p>

{% for role, label in [("donor", "Donors (messes)"), ("receiver", "Receivers (NGOs)"), ("volunteer", "Volunteers")] %}
<section>
  <h2>{{ label }}</h2>
  <ul class="personas">
    {% for p in groups[role] %}
    <li>
      <a href="{{ url_for('main.select_role', persona_id=p.id) }}">{{ p.display_name }}</a>
      <span>- {{ p.org_name }}</span>
    </li>
    {% endfor %}
  </ul>
</section>
{% endfor %}
{% endblock %}


--- surpluslink\surplus_link\templates\about.html ---
{% extends "base.html" %}
{% block title %}About{% endblock %}
{% block content %}
<h1>About SurplusLink</h1>
<p>Synthetic-data demo only. No real addresses, listings, or personal details.</p>

<h2>Proposed business models</h2>
<p>All business models below are proposals. None is in operation, none is priced with validated data, and none is a tax or legal benefit claim.</p>
<h3>Target customer</h3><p>Hostel messes and catering kitchens that produce surplus cooked food, and NGOs that need food donations.</p>
<h3>Proposed payer</h3><p>Donor subscription: a mess pays for coordination tools and periodic impact reports. CSR sponsorship: a company funds coordination and reporting for a named pilot zone, with its name shown only with the sponsor's agreement.</p>
<h3>Revenue model (proposed)</h3><p>Monthly donor subscription for coordination and impact reports. Optional CSR sponsorship packages for a pilot zone.</p>
<h3>Pricing assumptions (unvalidated)</h3><ul><li>No price has been tested with any mess, NGO or sponsor.</li><li>Any subscription figure is an assumption to be validated in customer interviews before use.</li><li>Sponsorship pricing depends on zone size and reporting depth; none is set.</li></ul>
{% endblock %}


--- surpluslink\surplus_link\templates\board.html ---
{% extends "base.html" %}
{% block title %}Volunteer board{% endblock %}
{% block content %}
<h1>Volunteer pickup board</h1>
<p class="notice">Claimed listings waiting for a volunteer. Times are IST. Pickup-by is a donor-provided collection deadline, not a guarantee of food safety.</p>

<section class="board" data-refresh-seconds="12">
  <p class="helper">Last updated <span id="last-updated">{{ last_updated_utc | ist }}</span>. <a href="{{ request.path }}">Refresh now</a></p>

  <h2>Open pickups</h2>
  {% if board.open %}
  <ol class="matches">
    {% for item in board.open %}
    <li class="match">
      <h3>{{ item.description }}</h3>
      <p>{{ item.quantity_kg }} kg from {{ item.donor_name }} to {{ item.receiver_name }}</p>
      <p>Pickup-by {{ item.pickup_by_utc | ist }}</p>
      {% if item.eligible %}
      <p class="tag-eligible">Suitable for you</p>
      <form method="post" action="{{ url_for('volunteering.accept_pickup_view', listing_id=item.listing_id) }}"><button type="submit" class="btn">Accept pickup</button></form>
      {% else %}
      <p class="tag-ineligible">Not suitable</p>
      <ul class="reasons">
        {% for r in item.reasons %}<li>{{ r }}</li>{% endfor %}
      </ul>
      {% endif %}
    </li>
    {% endfor %}
  </ol>
  {% else %}
  <p class="notice">No open pickups right now.</p>
  {% endif %}

  <h2>My pickups</h2>
  {% if board.mine %}
  <ol class="matches">
    {% for item in board.mine %}
    <li class="match">
      <h3>{{ item.description }}</h3>
      <p>Status: {{ item.status|capitalize }}</p>
      <p>Pickup-by {{ item.pickup_by_utc | ist }}</p>
      <p><a href="{{ url_for('donations.listing_detail', listing_id=item.listing_id) }}">Open listing and timeline</a></p>
      {% if item.status == 'claimed' %}
      <form method="post" action="{{ url_for('volunteering.collect_view', listing_id=item.listing_id) }}"><button type="submit" class="btn">Mark collected</button></form>
      {% endif %}
      {% if item.status == 'collected' %}
      <form method="post" action="{{ url_for('volunteering.deliver_view', listing_id=item.listing_id) }}"><button type="submit" class="btn">Mark delivered</button></form>
      {% endif %}
    </li>
    {% endfor %}
  </ol>
  {% else %}
  <p class="notice">No pickups assigned to you yet.</p>
  {% endif %}
</section>

<script src="{{ url_for('static', filename='refresh.js') }}" defer></script>
{% endblock %}


--- surpluslink\surplus_link\templates\donate.html ---
{% extends "base.html" %}
{% block title %}Post surplus food{% endblock %}
{% block content %}
<h1>Post surplus food</h1>
<p>Takes about a minute. Pickup-by is the collection deadline you set, in IST.</p>

{% if errors %}
<div class="error-summary" role="alert">
  <p>Please fix the highlighted fields.</p>
</div>
{% endif %}

<form method="post" action="{{ url_for('donations.new_listing') }}" novalidate>
  <div class="field">
    <label for="description">Food description</label>
    <input type="text" id="description" name="description" maxlength="200" value="{{ values.get('description', '') }}" required
      {% if errors.get('description') %}aria-invalid="true" aria-describedby="description-error"{% endif %}>
    {% if errors.get('description') %}<p class="field-error" id="description-error">{{ errors.get('description') }}</p>{% endif %}
  </div>

  <div class="field">
    <label for="quantity_kg">Quantity (kg)</label>
    <input type="number" id="quantity_kg" name="quantity_kg" step="0.1" min="0.1" max="1000" inputmode="decimal" value="{{ values.get('quantity_kg', '') }}" required
      {% if errors.get('quantity_kg') %}aria-invalid="true" aria-describedby="quantity_kg-error"{% endif %}>
    {% if errors.get('quantity_kg') %}<p class="field-error" id="quantity_kg-error">{{ errors.get('quantity_kg') }}</p>{% endif %}
  </div>

  <div class="field">
    <label for="pickup_by">Pickup-by deadline (IST)</label>
    <input type="datetime-local" id="pickup_by" name="pickup_by" value="{{ values.get('pickup_by', '') }}" required
      {% if errors.get('pickup_by') %}aria-invalid="true" aria-describedby="pickup_by-error"{% endif %}>
    <p class="helper">The collection deadline you set, in IST. Donor-provided, not a food-safety guarantee.</p>
    {% if errors.get('pickup_by') %}<p class="field-error" id="pickup_by-error">{{ errors.get('pickup_by') }}</p>{% endif %}
  </div>

  <div class="field">
    <label for="storage_type">Storage type</label>
    <select id="storage_type" name="storage_type" required
      {% if errors.get('storage_type') %}aria-invalid="true" aria-describedby="storage_type-error"{% endif %}>
      <option value="" disabled {% if not values.get('storage_type') %}selected{% endif %}>Choose storage</option>
      {% for key, label in storage_options %}
      <option value="{{ key }}" {% if values.get('storage_type') == key %}selected{% endif %}>{{ label }}</option>
      {% endfor %}
    </select>
    {% if errors.get('storage_type') %}<p class="field-error" id="storage_type-error">{{ errors.get('storage_type') }}</p>{% endif %}
  </div>

  <div class="field">
    <label for="handling_notes">Handling information (optional)</label>
    <textarea id="handling_notes" name="handling_notes" maxlength="500" rows="3"
      {% if errors.get('handling_notes') %}aria-invalid="true" aria-describedby="handling_notes-error"{% endif %}>{{ values.get('handling_notes', '') }}</textarea>
    <p class="helper">e.g. keep covered, reheated before serving, contains cooked rice</p>
    {% if errors.get('handling_notes') %}<p class="field-error" id="handling_notes-error">{{ errors.get('handling_notes') }}</p>{% endif %}
  </div>

  <fieldset {% if errors.get('allergens') %}aria-invalid="true" aria-describedby="allergens-error"{% endif %}>
    <legend>Allergens present (tick all that apply)</legend>
    {% for a in allergen_options %}
    <label class="check"><input type="checkbox" name="allergens" value="{{ a }}" {% if a in values.getlist('allergens') %}checked{% endif %}> {{ a|capitalize }}</label>
    {% endfor %}
    <p class="helper">As declared by the donor. SurplusLink does not verify allergen information.</p>
    {% if errors.get('allergens') %}<p class="field-error" id="allergens-error">{{ errors.get('allergens') }}</p>{% endif %}
  </fieldset>

  <button type="submit" class="btn">Post surplus</button>
</form>

<p class="notice">SurplusLink coordinates donations and does not certify food safety.</p>
{% endblock %}


