--- surpluslink\surplus_link\templates\listing.html ---
{% extends "base.html" %}
{% block title %}Listing #{{ listing.id }}{% endblock %}
{% block content %}
{% if show_created %}
<div class="confirm" role="status"><strong>Posted.</strong> Your surplus listing is saved with status Posted. Matching and claiming are available now. Volunteers accept pickups after a receiver claims the listing.</div>
{% endif %}

<h1>Listing #{{ listing.id }}</h1>

<dl class="listing">
  <dt>Food description</dt>
  <dd>{{ listing.description }}</dd>
  <dt>Quantity</dt>
  <dd>{{ '%g' % listing.quantity_kg }} kg</dd>
  <dt>Pickup-by deadline (IST)</dt>
  <dd>{{ listing.pickup_by_utc | ist }}</dd>
  <dt>Storage type</dt>
  <dd>{{ listing.storage_type|capitalize }}</dd>
  <dt>Handling information</dt>
  <dd>{{ listing.handling_notes or "None given" }}</dd>
  <dt>Allergens</dt>
  <dd>{{ allergen_list|join(", ") if allergen_list else "None declared by donor" }}</dd>
  <dt>Donor organisation</dt>
  <dd>{{ listing.donor_name }}</dd>
  <dt>Posted at (IST)</dt>
  <dd>{{ listing.created_at_utc | ist }}</dd>
</dl>
{% if claimed_ok %}<div class="confirm" role="status"><strong>Claimed.</strong> Your organisation has reserved this listing. Volunteers can now accept the pickup from the volunteer board.</div>{% endif %}
{% if claim_message %}<div class="error-summary" role="alert"><p>{{ claim_message }}</p></div>{% endif %}
{% if vol_message %}<div class="error-summary" role="alert"><p>{{ vol_message }}</p></div>{% endif %}{% if vol_ok_text %}<div class="confirm" role="status">{{ vol_ok_text }}</div>{% endif %}

<section class="timeline" data-refresh-seconds="12"><p><strong>Status:</strong> {{ listing.status|capitalize }}</p>
<p><strong>Claimed by:</strong> {% if claimant_name %}{{ claimant_name }}{% else %}Not yet claimed{% endif %}</p>
<p><strong>Volunteer:</strong> {% if volunteer_name %}{{ volunteer_name }}{% else %}Not yet assigned{% endif %}</p>
{% if current_persona and current_persona.role == 'volunteer' %}
  {% if can_accept %}<form method="post" action="{{ url_for('volunteering.accept_pickup_view', listing_id=listing.id) }}"><button type="submit" class="btn">Accept pickup</button></form>{% endif %}
  {% if can_collect %}<form method="post" action="{{ url_for('volunteering.collect_view', listing_id=listing.id) }}"><button type="submit" class="btn">Mark collected</button></form>{% endif %}
  {% if can_deliver %}<form method="post" action="{{ url_for('volunteering.deliver_view', listing_id=listing.id) }}"><button type="submit" class="btn">Mark delivered</button></form>{% endif %}
{% endif %}
{% if current_persona and current_persona.role == 'receiver' and listing.status == 'posted' %}<form method="post" action="{{ url_for('claiming.claim_view', listing_id=listing.id) }}"><button type="submit" class="btn">Claim for {{ current_persona.org_name }}</button></form>{% endif %}
<h2>Status timeline</h2><p class="helper">Last updated <span id="last-updated">{{ last_updated_utc | ist }}</span>. <a href="{{ request.path }}">Refresh now</a></p><ol class="events">{% for e in timeline %}<li>{% if e.from_status == e.to_status %}<strong>Volunteer assigned</strong>{% else %}<strong>{{ e.to_status|capitalize }}</strong>{% endif %} at {{ e.at_utc | ist }}{% if e.actor %} by {{ e.actor }}{% endif %}</li>{% else %}<li>No status events recorded.</li>{% endfor %}</ol></section>

<p class="notice">Pickup-by is a donor-provided collection deadline, not a guarantee of food safety.</p>

<p>
  {% if current_persona and current_persona.role == 'donor' %}<a href="{{ url_for('donations.new_listing') }}">Post another</a>{% endif %}
  <a href="{{ url_for('main.home') }}">Back to home</a>
</p>
<p><a class="btn" href="{{ url_for('matching.listing_matches', listing_id=listing.id) }}">See ranked matches</a></p>
<script src="{{ url_for('static', filename='refresh.js') }}" defer></script>
{% endblock %}


--- surpluslink\surplus_link\templates\matches.html ---
{% extends "base.html" %}
{% block title %}Ranked matches{% endblock %}
{% block content %}
<h1>Ranked matches for listing #{{ listing.id }}</h1>

<dl class="listing">
  <dt>Food</dt>
  <dd>{{ listing.description }}</dd>
  <dt>Quantity</dt>
  <dd>{{ '%g' % listing.quantity_kg }} kg</dd>
  <dt>Pickup-by (IST)</dt>
  <dd>{{ listing.pickup_by_utc | ist }}</dd>
  <dt>Storage</dt>
  <dd>{{ listing.storage_type | capitalize }}</dd>
  <dt>Allergens</dt>
  <dd>{{ listing.allergens or "None declared" }}</dd>
</dl>

{% if not result.listing_open %}
<div class="error-summary"><p>{{ result.listing_reason }}</p></div>
{% else %}

<h2>Receivers (NGOs)</h2>
{% if not (result.receivers | selectattr("eligible") | list) %}
<p class="notice">No suitable receivers right now. Reasons are listed below.</p>
{% endif %}
<ol class="matches">
{% for r in result.receivers %}
  <li class="match">
    <h3>{{ r.name }}</h3>
    {% if r.eligible %}
    <p class="tag-eligible">Eligible</p>
    <p>Score {{ r.score }} / 100</p>
    <div class="table-wrap">
    <table class="breakdown">
      <thead><tr><th>Factor</th><th>Value</th><th>Points</th></tr></thead>
      <tbody>
      {% for b in r.breakdown %}
        <tr><td>{{ b.factor }}</td><td>{{ b.value }}</td><td>{{ b.points }} / {{ b.max_points }}</td></tr>
      {% endfor %}
      </tbody>
    </table>
    </div>
    <p>Distance {{ r.distance_km }} km, travel about {{ r.travel_min }} min (assumed)</p>
    {% else %}
    <p class="tag-ineligible">Not eligible</p>
    <ul class="reasons">
      {% for reason in r.reasons %}<li>{{ reason }}</li>{% endfor %}
    </ul>
    {% endif %}
  </li>
{% endfor %}
</ol>

<h2>Volunteers</h2>
{% if not (result.volunteers | selectattr("eligible") | list) %}
<p class="notice">No suitable volunteers right now. Reasons are listed below.</p>
{% endif %}
<ol class="matches">
{% for v in result.volunteers %}
  <li class="match">
    <h3>{{ v.name }}</h3>
    {% if v.eligible %}
    <p class="tag-eligible">Eligible</p>
    <p>Score {{ v.score }} / 100</p>
    <div class="table-wrap">
    <table class="breakdown">
      <thead><tr><th>Factor</th><th>Value</th><th>Points</th></tr></thead>
      <tbody>
      {% for b in v.breakdown %}
        <tr><td>{{ b.factor }}</td><td>{{ b.value }}</td><td>{{ b.points }} / {{ b.max_points }}</td></tr>
      {% endfor %}
      </tbody>
    </table>
    </div>
    <p>Distance {{ v.distance_km }} km, travel about {{ v.travel_min }} min (assumed)</p>
    <p>Estimated collection {{ v.collection_time_ist }} IST</p>
    {% else %}
    <p class="tag-ineligible">Not eligible</p>
    <ul class="reasons">
      {% for reason in v.reasons %}<li>{{ reason }}</li>{% endfor %}
    </ul>
    {% endif %}
  </li>
{% endfor %}
</ol>
{% endif %}

<h2>Assumptions</h2>
<ul>
{% for a in result.assumptions %}
  <li>{{ a }}</li>
{% endfor %}
</ul>

<p><a href="{{ url_for('donations.listing_detail', listing_id=listing.id) }}">Back to listing</a></p>
