// SurplusLink lightweight refresh: re-fetches the page every N seconds and swaps
// the innerHTML of the section[data-refresh-seconds] element. Vanilla JS only.
(function () {
  "use strict";

  var FAILURE_SUFFIX = " (refresh failed, showing last good data)";

  function currentStamp() {
    return document.getElementById("last-updated");
  }

  function markFailed() {
    var stamp = currentStamp();
    if (stamp && stamp.textContent.indexOf(FAILURE_SUFFIX) === -1) {
      stamp.textContent = stamp.textContent + FAILURE_SUFFIX;
    }
  }

  function refreshOnce(section, parser) {
    return fetch(window.location.href, {
      cache: "no-store",
      headers: { "X-Refresh": "1" }
    })
      .then(function (response) {
        if (!response.ok) {
          throw new Error("HTTP " + response.status);
        }
        return response.text();
      })
      .then(function (text) {
        var doc = parser.parseFromString(text, "text/html");
        var fresh = doc.querySelector("section[data-refresh-seconds]");
        if (!fresh) {
          throw new Error("Refresh section missing from response");
        }
        section.innerHTML = fresh.innerHTML;
        var freshStamp = doc.getElementById("last-updated");
        var stamp = currentStamp();
        if (stamp && freshStamp) {
          stamp.textContent = freshStamp.textContent;
        }
      })
      .catch(function () {
        markFailed();
      });
  }

  document.addEventListener("DOMContentLoaded", function () {
    var section = document.querySelector("section[data-refresh-seconds]");
    if (!section) {
      return;
    }
    var seconds = parseInt(section.getAttribute("data-refresh-seconds"), 10);
    if (!seconds || seconds < 1) {
      seconds = 12;
    }
    var parser = new DOMParser();
    window.setInterval(function () {
      refreshOnce(section, parser);
    }, seconds * 1000);
  });
})();

--- surpluslink\surplus_link\static\style.css ---
/* SurplusLink base styles: mobile-first, single column by default. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  margin: 0;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

img,
pre,
table {
  max-width: 100%;
}

pre {
  overflow-x: auto;
}

.container {
  max-width: 960px;
  margin: 0 auto;
  padding: 12px;
}

/* Banner shown on every page */
.demo-banner {
  background: #fff3cd;
  border-bottom: 1px solid #e0a800;
  padding: 8px 12px;
  font-weight: 600;
}

.site-header {
  padding: 12px;
}

.persona-line {
  margin-top: 4px;
}

.site-footer {
  background: #f1f1f1;
  padding: 12px;
  font-size: 0.9rem;
  margin-top: 24px;
}

/* Buttons and links styled as buttons */
.btn {
  min-height: 44px;
  min-width: 44px;
  padding: 10px 14px;
  display: inline-flex;
  align-items: center;
  border-radius: 6px;
  background: #1b5e20;
  color: #fff;
  text-decoration: none;
  border: 0;
  font: inherit;
  cursor: pointer;
}

.persona-list {
  list-style: none;
  padding: 0;
}

.persona-list li {
  margin-bottom: 8px;
}

/* Under 600px everything stacks in one column. */
@media (max-width: 599px) {
  .btn {
    width: 100%;
    justify-content: center;
  }
}

.field { margin-bottom: 1rem; }
.field label, fieldset legend { display: block; font-weight: 600; margin-bottom: 0.25rem; }
input[type=text], input[type=number], input[type=datetime-local], select, textarea { width: 100%; max-width: 100%; min-height: 44px; font-size: 1rem; padding: 0.5rem; box-sizing: border-box; border: 1px solid #888; border-radius: 4px; font-family: inherit; }
textarea { min-height: 5rem; }
.check { display: flex; align-items: center; min-height: 44px; gap: 0.5rem; }
fieldset { border: 1px solid #ccc; border-radius: 6px; padding: 0.5rem 0.75rem; margin: 0 0 1rem; }
.field-error { color: #a40000; margin: 0.25rem 0 0; font-weight: 600; }
.error-summary { border: 2px solid #a40000; padding: 0.5rem 0.75rem; border-radius: 6px; margin-bottom: 1rem; color: #a40000; }
.helper { color: #555; font-size: 0.9rem; margin: 0.25rem 0 0; }
.notice { font-size: 0.9rem; color: #555; }
.confirm { background: #e8f5e9; border: 1px solid #2e7d32; padding: 0.6rem 0.8rem; border-radius: 6px; margin-bottom: 1rem; }
dl.listing dt { font-weight: 600; margin-top: 0.6rem; }
dl.listing dd { margin: 0 0 0.2rem 0; overflow-wrap: anywhere; }
.match { border:1px solid #ccc; border-radius:6px; padding:0.6rem 0.75rem; margin-bottom:0.75rem; list-style:none; }
.match h3 { margin:0 0 0.25rem; font-size:1.05rem; overflow-wrap:anywhere; }
.tag-eligible { color:#1b5e20; font-weight:600; }
.tag-ineligible { color:#a40000; font-weight:600; }
table.breakdown { width:100%; border-collapse:collapse; font-size:0.9rem; margin-top:0.4rem; }
table.breakdown th, table.breakdown td { text-align:left; padding:0.3rem; border-bottom:1px solid #eee; vertical-align:top; overflow-wrap:anywhere; }
.table-wrap { overflow-x:auto; }
ul.reasons { padding-left:1.1rem; margin:0.3rem 0; }
ol.matches { padding:0; list-style:none; }
form { margin: 0.5rem 0; }
button.btn { border: 0; font: inherit; cursor: pointer; }
.timeline { margin-top: 1.25rem; }
ol.events { padding-left: 1.2rem; }
ol.events li { margin-bottom: 0.35rem; overflow-wrap: anywhere; }
section.timeline .helper, section.board .helper { margin: 0.25rem 0 0.5rem; }
.match form { max-width: 100%; }
.match button { max-width: 100%; }
@media (max-width: 600px) { body { padding-left: 0.75rem; padding-right: 0.75rem; } dl.listing dd { overflow-wrap: anywhere; } }
.impact-grid { margin: 0.5rem 0 1rem; }
.impact-grid dd { font-size: 1.1rem; font-weight: 600; }

