  <h2>{{ label }}</h2>
  <ul class="personas">
    {% for p in groups[role] %}
    <li>
      <a href="{{ url_for('main.select_role', persona_id=p.id) }}">{{ p.display_name }}</a>
      <span>- {{ p.org_name }}</span>
    </li>
    {% endfor %}
  </ul>
</section>
{% endfor %}
{% endblock %}


