        page = ctx.new_page()
        errors, failed, bad = [], [], []
        page.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
        page.on("pageerror", lambda e: errors.append("pageerror: " + str(e)))
        page.on("requestfailed", lambda r: failed.append(r.url + " " + str(r.failure)))
        page.on("response", lambda r: bad.append(str(r.status) + " " + r.url) if r.status >= 400 else None)
        resp = page.goto(BASE + path, wait_until="load")
        page.wait_for_timeout(1000)
        data = {"status": resp.status}
        data.update(page.evaluate(MEASURE_JS))
        if shot:
