/* SurplusLink visual system (CP1). Warm cream, forest green, restrained amber.
   Mobile-first, single column by default. Visual only. */

/* ---------- Tokens ---------- */
:root {
  --cream: #faf6ec;
  --surface: #ffffff;
  --ink: #1d2a22;
  --muted: #4a5a50;
  --forest: #1f4d32;
  --forest-dark: #173a26;
  --amber-text: #7a4a00;
  --amber-bg: #fdf1d6;
  --amber-border: #c98a00;
  --red-text: #9b1c1c;
  --red-bg: #fbe9e9;
  --line: #e2dccb;
  --focus: #7a4a00;
  --radius: 8px;
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 24px;
  --s6: 32px;
}

/* ---------- Base ---------- */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  background: var(--cream);
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.5;
  margin: 0;
}

body {
  padding: 0 var(--s4) var(--s6);
  overflow-wrap: anywhere;
}

img,
svg,
video,
pre,
table {
  max-width: 100%;
}

pre {
  overflow-x: auto;
}

/* ---------- Headings and links ---------- */
h1 {
  font-size: 1.75rem;
  line-height: 1.25;
}

h2 {
  font-size: 1.25rem;
  line-height: 1.25;
  margin-top: var(--s5);
}

h3 {
  font-size: 1.05rem;
  line-height: 1.25;
}

a {
  color: var(--forest);
  text-underline-offset: 2px;
}

/* ---------- Focus (never remove without replacement) ---------- */
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
summary:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------- Skip link ---------- */
.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
}

.skip-link:focus {
  left: var(--s4);
  top: var(--s2);
  z-index: 10;
  background: var(--forest);
  color: #fff;
  padding: var(--s2) var(--s3);
  border-radius: var(--radius);
}

/* ---------- Layout ---------- */
header,
main,
footer {
  max-width: 40rem;
  margin: 0 auto;
}

header {
  padding-top: var(--s4);
}

nav a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  margin-right: var(--s4);
}

main a:not(.btn):not(.skip-link) {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  padding: 0 var(--s1);
}


.container {
  max-width: 40rem;
  margin: 0 auto;
}

/* ---------- Badges and notices ---------- */
.badge {
  display: inline-block;
  background: var(--amber-bg);
  border: 1px solid var(--amber-border);
  color: var(--amber-text);
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 0.85rem;
  font-weight: 600;
}

.demo-banner {
  background: var(--amber-bg);
  border-bottom: 1px solid var(--amber-border);
  color: var(--amber-text);
  padding: var(--s2) var(--s3);
  font-weight: 600;
}

.acting {
  background: #e9f1ec;
  border-left: 4px solid var(--forest);
  padding: var(--s2) var(--s3);
  border-radius: 6px;
  margin: var(--s3) 0;
}

.persona-line {
  margin-top: var(--s1);
}

.notice {
  color: var(--muted);
  font-size: 0.95rem;
}

.helper {
  color: var(--muted);
  font-size: 0.9rem;
  margin: var(--s1) 0 0;
}

.tag-eligible {
  color: #1b5e20;
  background: #e6f2e9;
  padding: 2px 8px;
  border-radius: 999px;
  font-weight: 600;
}

