{% if current_persona and current_persona.role == 'donor' %}<a href="{{ url_for('donations.new_listing') }}">Post surplus</a>{% endif %}
{% if current_persona and current_persona.role == 'volunteer' %}<a href="{{ url_for('volunteering.board') }}">Volunteer board</a>{% endif %}
